CREATE DATABASE IF NOT EXISTS temp_card CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE temp_card;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('admin','user','operator') NOT NULL, must_change_password TINYINT(1) NOT NULL DEFAULT 0, is_deleted TINYINT(1) NOT NULL DEFAULT 0, session_version INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contractors (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE);
CREATE TABLE access_areas (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE app_sessions (id VARCHAR(128) PRIMARY KEY, data MEDIUMBLOB NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE cards (id INT AUTO_INCREMENT PRIMARY KEY, barcode VARCHAR(32) NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, national_code VARCHAR(10) NOT NULL, job_title VARCHAR(150) NOT NULL DEFAULT '---', photo VARCHAR(255) NOT NULL, contractor_id INT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, access_area VARCHAR(255) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, disabled_reason VARCHAR(255) DEFAULT NULL, created_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (contractor_id) REFERENCES contractors(id), FOREIGN KEY (created_by) REFERENCES users(id), UNIQUE KEY unique_national_code (national_code), INDEX (created_at)) ENGINE=InnoDB;
CREATE TABLE access_logs (id INT AUTO_INCREMENT PRIMARY KEY, card_id INT NOT NULL, operator_id INT NOT NULL, action ENUM('entry','exit') NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (card_id) REFERENCES cards(id), FOREIGN KEY (operator_id) REFERENCES users(id), INDEX (card_id, created_at)) ENGINE=InnoDB;
